import {osmosisState,osmosisCases}from './osmosis-models.js?v=20261023-physicscomplete01';
export function osmosisFigure(id='dilute',step=0){const f=osmosisState(id,step),x=240-65*f.scale,y=150-80*f.scale;return `<svg class="shell-diagram" viewBox="0 0 480 330" role="img" aria-label="Plant cell: ${osmosisCases.find(c=>c.id===id)?.effect||'water movement'}; cell wall fixed, cell contents ${f.direction<0?'shrinking':f.direction>0?'expanding':'unchanged'} in this model"><rect x="150" y="40" width="180" height="220" rx="22" fill="none" stroke="#d4dfe7" stroke-width="8"/><rect x="${x}" y="${y}" width="${130*f.scale}" height="${160*f.scale}" rx="22" fill="#ed8b78" fill-opacity=".3" stroke="#ed8b78" stroke-width="3"/><rect x="${x+15}" y="${y+20}" width="${100*f.scale}" height="${120*f.scale}" rx="18" fill="#b7c8d6" fill-opacity=".6"/>${Array.from({length:6},(_,i)=>`<rect x="${x+25+(i%2)*45*f.scale}" y="${y+35+Math.floor(i/2)*35*f.scale}" width="10" height="10" rx="2" fill="#ed8b78"/>`).join('')}${Array.from({length:id==='dilute'?3:id==='equal'?6:10},(_,i)=>`<rect x="${35+(i%2)*55}" y="${60+Math.floor(i/2)*35}" width="12" height="12" rx="2" fill="#ed8b78"/>`).join('')}<path d="M80 135H145M135 128L145 135L135 142M145 180H80M90 173L80 180L90 187" fill="none" stroke="#f8f6f2" stroke-width="3"/><text x="70" y="120" text-anchor="middle" fill="#f8f6f2" font-size="12">Water in: ${f.inward}</text><text x="70" y="208" text-anchor="middle" fill="#f8f6f2" font-size="12">Water out: ${f.outward}</text><text x="240" y="295" text-anchor="middle" fill="#f8f6f2" font-size="13">Outer wall fixed · inner membrane changes</text><text x="240" y="321" text-anchor="middle" fill="#d4dfe7" font-size="12">Squares: solute stays on its own side · arrows: water only</text></svg>`;}
export function osmosisGraph({points=[],assessment=false}={}){const data=points.map(p=>[Number(p[0]),Number(p[1])]).filter(p=>p.every(Number.isFinite)),maxX=Math.max(.8,...data.map(p=>p[0])),maxY=Math.max(15,...data.map(p=>Math.abs(p[1]))),X=x=>70+x/maxX*340,Y=y=>145-y/maxY*100;const html=`<svg class="shell-diagram" viewBox="0 0 480 330" role="img" aria-label="Percentage mass change against concentration. ${data.map(([x,y])=>x+' mol per cubic decimetre: '+y+' percent').join('; ')}"><title>Plant-tissue results</title>${[-1,0,1].map(k=>`<path d="M70 ${Y(k*maxY)}H410" stroke="#b7c8d6" opacity=".4"/><text x="59" y="${Y(k*maxY)+4}" text-anchor="end" fill="#f8f6f2" font-size="12">${k*maxY}</text>`).join('')}<path d="M70 35V250H425" fill="none" stroke="#f8f6f2" stroke-width="2"/>${[0,.25,.5,.75,1].map(k=>`<text x="${X(maxX*k)}" y="271" text-anchor="middle" fill="#f8f6f2" font-size="12">${Number((maxX*k).toFixed(2))}</text>`).join('')}${data.length>1?`<polyline points="${[...data].sort((a,b)=>a[0]-b[0]).map(([x,y])=>X(x)+','+Y(y)).join(' ')}" fill="none" stroke="#ed8b78" stroke-width="2"/>`:''}${data.map(([x,y])=>`<circle cx="${X(x)}" cy="${Y(y)}" r="5" fill="#ed8b78" stroke="#f8f6f2"/>`).join('')}<text x="240" y="304" text-anchor="middle" fill="#f8f6f2" font-size="13">Solution concentration / mol dm⁻³</text><text x="18" y="150" text-anchor="middle" transform="rotate(-90 18 150)" fill="#f8f6f2" font-size="13">Mass change / %</text></svg>`;return assessment?html.replaceAll('#f8f6f2','#182e44').replaceAll('#b7c8d6','#526f86'):html;}
export function osmosisBench(revealed=false){return `<svg class="shell-diagram" viewBox="0 0 480 300" role="img" aria-label="Five labelled solutions with equal sized plant tissue samples; illustrative experiment"><path d="M20 225H460" stroke="#b7c8d6" stroke-width="3"/>${[0,.2,.4,.6,.8].map((c,i)=>{const x=30+i*89;return`<path d="M${x} 80V215H${x+65}V80" fill="none" stroke="#f8f6f2" stroke-width="2"/><rect x="${x+2}" y="125" width="61" height="87" fill="#b7c8d6" fill-opacity="${.15+c*.3}"/><rect x="${x+24}" y="142" width="18" height="60" rx="5" fill="#ed8b78"/><text x="${x+33}" y="252" text-anchor="middle" fill="#f8f6f2" font-size="14">${c}</text>`;}).join('')}<text x="240" y="285" text-anchor="middle" fill="#d4dfe7" font-size="12">Sucrose / mol dm⁻³ · equal volume, time and temperature</text></svg>`;}
